export const collateralRepairDefinitions={
 collateralRepair:{title:'Inspect three balance-sheet adjustments under one invented equity-ratio rule',fields:[
  ['initialAssets','Initial collateral asset value (CAD)',60000,1000,500000,1000],
  ['financedShare','Initial asset value financed by the loan (%)',50,0,90,1],
  ['priceMove','Cumulative change in the original asset price (%)',-30,-90,20,1],
  ['equityFloor','Invented required equity-to-assets ratio (%)',40,10,80,1]
 ]}
};

export function collateralRepairLedger(d){
 const loan=d.initialAssets*d.financedShare/100,assets=d.initialAssets*(1+d.priceMove/100),equity=assets-loan,m=d.equityFloor/100;
 const loanReduction=Math.max(0,m*assets-equity),extraCollateral=loanReduction/(1-m);
 const sellValue=loanReduction===0?0:equity<=0?null:loanReduction/m;
 const cases=[{label:'Cash used to repay loan',external:loanReduction,sold:0,assets,loan:loan-loanReduction},{label:'Cash held as extra collateral',external:extraCollateral,sold:0,assets:assets+extraCollateral,loan}];
 if(sellValue!==null){const remainingAssets=sellValue===0?assets:equity/m;cases.push({label:'Sell assets and repay loan',external:0,sold:sellValue,assets:remainingAssets,loan:sellValue===0?loan:remainingAssets*(1-m)});}
 return {loan,assets,equity,initialEquity:d.initialAssets-loan,equityRatio:equity/assets,requiredRatio:m,loanReduction,extraCollateral,sellValue,cases:cases.map(c=>({...c,equity:c.assets-c.loan,ratio:(c.assets-c.loan)/c.assets,netOfNewCash:c.assets-c.loan-c.external}))};
}

export function collateralRepairResult(kind,d){
 if(kind!=='collateralRepair')throw Error('Unknown collateral-ratio illustration.');
 const p=collateralRepairLedger(d),xmin=Math.min(-60,d.priceMove),profile=[...new Set([...Array.from({length:41},(_,i)=>xmin+(20-xmin)*i/40),d.priceMove])].sort((a,b)=>a-b);
 return {metrics:[['Outside cash used to reduce the loan',p.loanReduction,'money'],['Outside cash held as extra collateral',p.extraCollateral,'money'],['Assets sold in the sale-only case',p.sellValue,'money',p.sellValue===null?'No sale-only repair':undefined]],
 note:'Original instantaneous balance-sheet illustration under an invented equity/assets requirement. Amounts are CAD, with no actual security, broker, jurisdictional margin schedule or eligibility calculation. The loan stays fixed during the selected asset-price move. Three mutually exclusive adjustments then target the same ratio: use outside cash to repay debt; add outside cash to collateral assets while leaving debt unchanged; or sell original assets and apply all proceeds to debt. The separate held-cash case is an assumed collateral arrangement, not a claim that a broker will permit cash to remain without netting the loan. If a firm applies a deposit against debt, the repayment case describes that accounting. A sale-only repair of a remaining funded account is unavailable when equity is zero or negative. No deadline, actual margin call, tax, fees, interest, further price move or lender approval is modeled. Adding outside cash is new funding, not recovered investment performance. '+(p.sellValue===null?'Sale-only rows are omitted from the resource and balance charts because that adjustment cannot restore a positive equity ratio in this scenario.':'Every displayed adjustment preserves the same pre-adjustment investment equity after subtracting its new outside funding.'),charts:[
  {id:'collateral-repair-ratio-profile',type:'line',title:'A fixed loan makes the equity ratio fall faster than the asset price',unit:'percent',unitLabel:'Account equity divided by total collateral assets · hypothetical ratio',xLabel:'Asset price change (%)',xMin:xmin,series:[{name:'Equity/assets before any adjustment',rows:profile.map(move=>({x:move,value:collateralRepairLedger({...d,priceMove:move}).equityRatio}))},{name:'Invented required ratio',dash:true,rows:profile.map(move=>({x:move,value:p.requiredRatio}))}],note:'The profile keeps the initial loan and asset value fixed, then replaces the cumulative price change. It spans at least −60% through +20%, extending left if the selected change is lower. Negative ratios indicate debt greater than asset value. The requirement is an entered assumption, not a current regulatory minimum or a prediction of a firm’s action.'},
  {id:'collateral-repair-resource-amounts',type:'groupbar',title:'The same target ratio requires different amounts of cash or assets sold',unit:'money',unitLabel:'Different resources required by separate adjustments · CAD',seriesNames:['New outside cash used','Original assets sold'],rows:p.cases.map(c=>({label:c.label,values:[c.external,c.sold]})),note:'Read each row as an alternative. Cash repaying a loan reduces debt; cash held as collateral increases assets and equity; a sale followed by debt repayment reduces both assets and debt. A sale-only row is omitted when it cannot restore a positive ratio. Zero outside cash in a feasible sale case does not mean there is no investment loss, execution cost or tax.'},
  {id:'collateral-repair-after-balances',type:'groupbar',title:'The post-adjustment asset and loan balances explain the different amounts',unit:'money',unitLabel:'Collateral asset value and loan principal · CAD',seriesNames:['Assets inside the collateral account','Loan owed'],rows:[{label:'Before adjustment',values:[p.assets,p.loan]},...p.cases.map(c=>({label:c.label,values:[c.assets,c.loan]}))],note:'Each adjustment uses its own denominator. The held-cash case includes the added cash in collateral assets and leaves the loan unchanged. The sale case applies all sale proceeds to the loan. Assets are shown at the same assumed execution price. No chart adds the alternatives together.'},
  {id:'collateral-repair-new-money-equity',type:'signedbar',title:'Subtracting new outside cash shows that a ratio repair does not reverse the price loss',unit:'money',unitLabel:'Account equity less new cash supplied for the adjustment · CAD',rows:[{label:'Initial investor capital',value:p.initialEquity},{label:'After price change',value:p.equity},...p.cases.map(c=>({label:c.label,value:c.netOfNewCash}))],note:'The initial capital and post-price equity differ by the original asset’s dollar price change. All adjustment rows subtract only their own new outside cash. Their equal net amount is an accounting reconciliation under the stated assumptions, not an annual return or a full household net-worth statement. Costs and tax would create additional changes.'},
  {id:'collateral-repair-threshold-matrix',type:'heatmap',title:'Cash needed to reduce debt depends on both the asset decline and the assumed threshold',unit:'money',unitLabel:'New outside cash applied directly to the loan · CAD',columns:['20%','30%','40%','50%'],rows:[0,-10,-20,-40,-60,-80].map(move=>({label:move+'%',values:[20,30,40,50].map(floor=>collateralRepairLedger({...d,priceMove:move,equityFloor:floor}).loanReduction)})),note:'Rows replace the cumulative asset-price move; columns replace the assumed required equity ratio. Initial asset value and financing share stay selected. Each cell uses debt repayment, not held cash or asset sales. Zero means no repayment is needed for that assumed ratio at that point; it does not establish that borrowing is appropriate or that the position can withstand another decline.'}
 ]};
}
